//! Compiles the Slint UI, and on Windows embeds the application icon.
//!
//! `assets/icon.ico` is generated by `scripts/make-icons.py`. Embedding it as a resource
//! gives the `.exe` its icon in Explorer. It does NOT reach the window's titlebar/taskbar
//! icon: winit registers its window class without one, so the `App` window sets `icon` to
//! `assets/icon.png` itself (see `ui/app.slint`); Slint embeds that image in the binary,
//! so nothing has to be installed next to it.
//!
//! Embedding needs a resource compiler (`rc.exe` for `msvc`, `windres` for `gnu`),
//! neither guaranteed present, particularly when cross-compiling. A missing icon must
//! never fail the build, so this reports and continues; the Slint compile still panics
//! on failure, since without it there is no UI at all.
//!
//! The gate is the TARGET OS (`CARGO_CFG_TARGET_OS`), read at run time, not a
//! `#[cfg(windows)]` on this build script: a build script is compiled for and runs on
//! the HOST, so a `cfg(windows)` here would be false whenever the Windows binary is
//! cross-compiled from Linux, and those binaries would ship without any icon. The
//! browser build (`wasm32`) targets no OS and embeds nothing.

fn main() {
    // Debug info (element ids and type names) lets the UI flow tests look widgets
    // up with `i_slint_backend_testing::ElementHandle`. Release builds go without,
    // except with the `ui-harness` feature: the slint-harness element queries need
    // the debug info, so `--release --features ui-harness` keeps it too.
    let harness = std::env::var_os("CARGO_FEATURE_UI_HARNESS").is_some();
    let debug = harness || std::env::var("PROFILE").map_or(true, |profile| profile != "release");
    let config = slint_build::CompilerConfiguration::new().with_debug_info(debug);
    slint_build::compile_with_config("ui/app.slint", config).unwrap();

    println!("cargo:rerun-if-env-changed=CARGO_CFG_TARGET_OS");
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("windows") {
        embed_icon();
    }
}

/// Embeds `assets/icon.ico` as the executable's Windows icon resource.
///
/// A twin of `apps/stacker-cli/build.rs`'s `embed_icon`: a build script cannot share
/// code across packages without a helper crate, so an edit to one must be mirrored in
/// the other.
fn embed_icon() {
    println!("cargo:rerun-if-changed=assets/icon.ico");
    let mut res = winresource::WindowsResource::new();
    res.set_icon("assets/icon.ico");
    if let Err(e) = res.compile() {
        println!(
            "cargo:warning=could not embed the application icon ({e}); the binary will build without one"
        );
    }
}
